// src/lib/og-logo.ts
// Shared base64 data URI of the AgroLink emblem, sized for use inside
// next/og ImageResponse cards (opengraph-image.tsx files). Embedded as a
// data URI rather than fetched by relative URL so OG image generation
// never depends on the site being publicly reachable at render time.

export const LOGO_DATA_URI = "data:image/png;base64,";
